double ft = 0.3048;
string siteTitle = Tama.Args.Get(args, "siteTitle", "");
int refId = Tama.Args.Get(args, "refInstanceId", 0);
int linkId = Tama.Args.Get(args, "linkId", 0);
double elev = Tama.Args.Get(args, "elev", 0.0) / ft;
Document site = null;
foreach (Document d in app.Documents) if (!d.IsLinked && d.Title == siteTitle) site = d;
if (site == null) throw new Exception("Site model not open");
var refLi = site.GetElement(new ElementId(refId)) as RevitLinkInstance;
if (refLi == null) throw new Exception("Reference instance not found");
var Tref = refLi.GetTransform();               // plot internal -> site internal (mirrored)
var Tt = Tref.Inverse;                          // site internal -> plot internal
Tt.Origin = new XYZ(Tt.Origin.X, Tt.Origin.Y, -elev);

var li = doc.GetElement(new ElementId(linkId)) as RevitLinkInstance;
if (li == null) throw new Exception("Link not found");
if (li.Pinned) throw new Exception("Link is pinned");
var t0 = li.GetTransform();
bool curMir = t0.BasisX.CrossProduct(t0.BasisY).Z < 0;
bool tgtMir = Tt.BasisX.CrossProduct(Tt.BasisY).Z < 0;
if (curMir != tgtMir) {
    ElementTransformUtils.MirrorElements(doc, new List<ElementId>{ li.Id }, Plane.CreateByNormalAndOrigin(XYZ.BasisX, t0.Origin), false);
    doc.Regenerate();
}
var t1 = li.GetTransform();
double ang = Math.Atan2(Tt.BasisX.Y, Tt.BasisX.X) - Math.Atan2(t1.BasisX.Y, t1.BasisX.X);
ElementTransformUtils.RotateElement(doc, li.Id, Line.CreateBound(t1.Origin, t1.Origin + XYZ.BasisZ), ang);
doc.Regenerate();
ElementTransformUtils.MoveElement(doc, li.Id, Tt.Origin - li.GetTransform().Origin);
doc.Regenerate();
var t = li.GetTransform();
double err = t.BasisX.DistanceTo(Tt.BasisX) + t.BasisY.DistanceTo(Tt.BasisY) + t.Origin.DistanceTo(Tt.Origin);
if (err > 1e-6) throw new Exception("Placement check failed (" + err + ") - rolled back.");
// plot origin in site internal coordinates
var pIn = t.Inverse.OfPoint(XYZ.Zero);
var rp = Tref.Origin;
return new {
  refInstance = refLi.Name, refOriginSite_m = new[]{Math.Round(rp.X*ft,4), Math.Round(rp.Y*ft,4), Math.Round(rp.Z*ft,4)},
  refRot = Math.Round(Math.Atan2(Tref.BasisX.Y, Tref.BasisX.X)*180/Math.PI,6), refMirrored = Tref.BasisX.CrossProduct(Tref.BasisY).Z < 0,
  link = li.Name, mirrored = t.BasisX.CrossProduct(t.BasisY).Z < 0,
  origin_m = new[]{Math.Round(t.Origin.X*ft,4), Math.Round(t.Origin.Y*ft,4), Math.Round(t.Origin.Z*ft,4)},
  rot = Math.Round(Math.Atan2(t.BasisX.Y, t.BasisX.X)*180/Math.PI,6),
  plotOriginInSiteInternal_m = new[]{Math.Round(pIn.X*ft,4), Math.Round(pIn.Y*ft,4), Math.Round(pIn.Z*ft,4)}
};
